<?php
require_once __DIR__ . '/../app/bootstrap.php';
require_auth();
$pdo = db();
$user = current_user();
$stats = [
    'total' => (int)$pdo->query("SELECT COUNT(*) FROM leads")->fetchColumn(),
    'open' => (int)$pdo->query("SELECT COUNT(*) FROM leads WHERE status IN ('new','contacted','qualified','proposal')")->fetchColumn(),
    'qualified' => (int)$pdo->query("SELECT COUNT(*) FROM leads WHERE status='qualified'")->fetchColumn(),
    'won' => (int)$pdo->query("SELECT COUNT(*) FROM leads WHERE status='won'")->fetchColumn(),
    'value' => (float)$pdo->query("SELECT COALESCE(SUM(value),0) FROM leads WHERE status IN ('new','contacted','qualified','proposal')")->fetchColumn(),
    'won_value' => (float)$pdo->query("SELECT COALESCE(SUM(value),0) FROM leads WHERE status='won'")->fetchColumn(),
    'overdue' => (int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status='pending' AND due_at IS NOT NULL AND due_at < NOW()")->fetchColumn(),
    'today_tasks' => (int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status='pending' AND due_at IS NOT NULL AND DATE(due_at)=CURDATE()")->fetchColumn(),
];
$recent = $pdo->query("SELECT * FROM leads ORDER BY created_at DESC LIMIT 8")->fetchAll();
$followups = $pdo->query("SELECT id,name,company,status,value,follow_up_at FROM leads WHERE follow_up_at IS NOT NULL AND follow_up_at >= NOW() ORDER BY follow_up_at ASC LIMIT 6")->fetchAll();
$tasks = $pdo->query("SELECT t.id,t.title,t.due_at,t.priority,l.id AS lead_id,l.name AS lead_name FROM tasks t LEFT JOIN leads l ON l.id=t.lead_id WHERE t.status='pending' ORDER BY t.due_at IS NULL,t.due_at ASC LIMIT 6")->fetchAll();
$stages = ['new'=>'New','contacted'=>'Contacted','qualified'=>'Qualified','proposal'=>'Proposal','won'=>'Won','lost'=>'Lost'];
$stageData = $pdo->query("SELECT status,COUNT(*) total,COALESCE(SUM(value),0) value FROM leads GROUP BY status")->fetchAll();
$stageMap=[];foreach($stageData as $row)$stageMap[$row['status']]=$row;
$sources=$pdo->query("SELECT COALESCE(NULLIF(source,''),'unknown') source,COUNT(*) total,COALESCE(SUM(value),0) value FROM leads GROUP BY COALESCE(NULLIF(source,''),'unknown') ORDER BY total DESC LIMIT 5")->fetchAll();
?>
